import React, { useState } from "react";
import { useEffect } from "react";
import { useLocation, useParams } from "react-router-dom";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import IGASolutionList from "src/views/pages/ITSolutionDetails/ITSolutionOverview/IGASolutionList";
import IGASolutionOptions from "src/views/pages/ITSolutionDetails/ITSolutionOverview/IGASolutionOptions/IGASolutionOptions";
import PlanSection from "src/views/pages/ITSolutionDetails/ITSolutionOverview/PlanSection";
import StreamlineIdentity from "src/views/pages/ITSolutionDetails/ITSolutionOverview/StreamlineIdentity";
import { toastError, toastSuccess } from "src/utils/utils";
import { use } from "i18next";
import { Box } from "@mui/material";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";
import OverviewImages from "src/views/pages/ITSolutionDetails/ITSolutionOverview/OverviewImages";
import { useAuth } from "src/hooks/useAuth";
import FallbackSpinner from "src/@core/components/spinner";

const ITSolutionOverviewPage = () => {
  const { setITSolutionId, setOverviewPlan, setSlug } = useAuth();
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const name = id.split("-").slice(0, -1).join("-");

  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  const [pdf, setPdf] = useState({});

  const [homeOverviewData, setHomeOverviewData] = useState({});

  const [overviewList, setOverviewList] = useState([]);
  const [subOverviewData, setSubOverviewData] = useState({});
  const [overviewValue, setOverviewValue] = useState("");

  const [overviewFeatures, setOverviewFeatures] = useState([]);
  const [overviewFeaturesTitle, setOverviewFeaturesTitle] = useState({});

  const [overviewImages, setOverviewImages] = useState([]);

  const [overviewPlanData, setOverviewPlanData] = useState([]);

  const cleanAndCapitalizeName = (str) =>
    str
      .replace(/-+/g, " ") // Replace one or more hyphens with a single space
      .trim() // Remove leading or trailing spaces
      .replace(/\b\w/g, (char) => char.toUpperCase());

  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
    setITSolutionId(itSolutionId);
    setSlug(name);
    document.title = `DWIT ${cleanAndCapitalizeName(name)}`;
  }, []);

  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const shouldAnimateBackground = () => {
    return (
      overviewList.length > 0 ||
      overviewFeatures.length > 0 ||
      overviewFeaturesTitle.length > 0 ||
      overviewPlanData.length > 0 ||
      overviewImages.length > 0
    );
  };

  // useEffect(() => {
  //   if (!shouldAnimateBackground()) return; // Skip animation if data is missing

  //   const handleScroll = () => {
  //     const offset = window.pageYOffset || document.documentElement.scrollTop;
  //     setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
  //   };

  //   window.addEventListener("scroll", handleScroll);
  //   handleScroll(); // Initialize position

  //   return () => {
  //     window.removeEventListener("scroll", handleScroll);
  //   };
  // }, [
  //   overviewList,
  //   overviewFeatures,
  //   overviewFeaturesTitle,
  //   overviewPlanData,
  //   overviewImages,
  // ]);

  const fetchOverviewMainTitle = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_HOME.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setHomeOverviewData(responseData[0]);
        } else {
          setHomeOverviewData({});
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchDownloadPDF = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_PDF.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        if (responseData.length > 0) {
          responseData.map((item) => setPdf(item));
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchITSolutionsOverviewList = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW.list(itSolutionId))
      .then((response) => {
        setOverviewList(response.data.data);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setOverviewValue(responseData[0].title);
        }
        responseData.map((item) => {
          fetchITSubSolutionsOverview(item.id, item.title);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchITSubSolutionsOverview = (id, title) => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_SUB_OVERVIEW.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setSubOverviewData((prevData) => ({
          ...prevData,
          [title]: responseData,
        }));
      })

      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchOverviewFeatures = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_FEATURES.list(itSolutionId))
      .then((response) => {
        setOverviewFeatures(response.data.data);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchOverviewFeaturesTitle = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_FEATURES_TITLE.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        responseData.map((item) => {
          setOverviewFeaturesTitle(item);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchOverviewPlan = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_PLAN.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        setOverviewPlanData(responseData);

        setOverviewPlan(responseData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchOverviewImages = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_OVERVIEW_IMAGES.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        setOverviewImages(responseData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchOverviewMainTitle();
    fetchDownloadPDF();
    fetchITSolutionsOverviewList();
    fetchOverviewFeatures();
    fetchOverviewFeaturesTitle();
    fetchOverviewPlan();
    fetchOverviewImages();
  }, [itSolutionId]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      {shouldAnimateBackground() ? (
        <Box
          sx={{
            position: "relative",
            minHeight: "100vh",
            overflowX: "hidden",
            overflowY: "auto",
            scrollBehavior: "smooth",
            transition: "2s ease-in-out",
          }}
        >
          <Box
            sx={{
              backgroundImage: {
                xs: `url(${bgImgSmall})`,
                sm: `url(${bgImg})`,
              },
              backgroundRepeat: "no-repeat",
              backgroundPosition: `right ${backgroundPositionY}px`,
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              zIndex: -1,
              pointerEvents: "none",
              transition: "background-position 1.5s ease-in-out",
            }}
          />
          <StreamlineIdentity homeOverviewData={homeOverviewData} pdf={pdf} />
          {(homeOverviewData?.title_2 || overviewList.length > 0) && (
            <IGASolutionOptions
              homeOverviewData={homeOverviewData}
              overviewList={overviewList}
              subOverviewData={subOverviewData}
              overviewValue={overviewValue}
            />
          )}
          {(homeOverviewData?.title_3 ||
            Object.keys(overviewFeaturesTitle).length > 0) && (
            <IGASolutionList
              homeOverviewData={homeOverviewData}
              overviewFeatures={overviewFeatures}
              overviewFeaturesTitle={overviewFeaturesTitle}
            />
          )}
          {overviewPlanData.length > 0 && (
            <PlanSection
              homeOverviewData={homeOverviewData}
              overviewPlanData={overviewPlanData}
            />
          )}
          {overviewImages.length > 0 && (
            <OverviewImages overviewImages={overviewImages} />
          )}
        </Box>
      ) : (
        <StreamlineIdentity homeOverviewData={homeOverviewData} pdf={pdf} />
      )}
    </>
  );
};

export default ITSolutionOverviewPage;
