import {
  Box,
  Container,
  createTheme,
  Fade,
  Grid,
  styled,
  Typography,
  useMediaQuery,
} from "@mui/material";
import Tab from "@mui/material/Tab";
import TabContext from "@mui/lab/TabContext";
import TabList from "@mui/lab/TabList";
import TabPanel from "@mui/lab/TabPanel";
import Tabs from "@mui/material/Tabs";
import React from "react";
import { useState } from "react";
import IGASolutionOptionsCard from "./IGASolutionOptionsCard";
import { useEffect } from "react";

const IGASolutionOptions = (props) => {
  const { homeOverviewData, overviewList, subOverviewData, overviewValue } =
    props;

  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "14px",
    [theme.breakpoints.up("sm")]: {
      fontSize: "16px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "18px",
    },
    fontWeight: 600,
    textTransform: "capitalize",
    wordBreak: "break-word",
    whiteSpace: "normal",
  }));
  const CustomTabPanel = styled(TabPanel)(({ theme }) => ({
    [theme.breakpoints.down("sm")]: {
      padding: 0,
    },
    [theme.breakpoints.up("sm")]: {
      padding: "25px",
    },
  }));
  const [value, setValue] = useState("");
  const handleChange = (event, newValue) => {
    setValue(newValue);
  };
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const isTablet = useMediaQuery("(min-width:1100px) and (max-width:1400px)");
  const isLarge = useMediaQuery(theme.breakpoints.up("lg"));

  useEffect(() => {
    setValue(overviewValue);
  }, [overviewValue]);

  return (
    <>
      <Container
        maxWidth={"xl"}
        sx={{
          p: { xs: 5, sm: 10, lg: 15, xl: 20 },
        }}
      >
        <Grid container rowGap={{ md: 8 }}>
          <Grid
            item
            xs={12}
            sx={{
              display: "flex",
              flexDirection: "column",
              gap: 3,
              px: { lg: 10 },
            }}
          >
            <Typography
              sx={{
                fontSize: { xs: "26px", sm: "28px", lg: "38px" },
                fontWeight: 500,
                lineHeight: {
                  xs: "34px",
                  sm: "60px",
                  lg: "70px",
                },
                color: "#201D28",
                textAlign: "center",
                textWrap: "wrap",
              }}
            >
              {homeOverviewData?.title_2}
            </Typography>
            <Typography
              sx={{
                fontSize: { xs: "14px", sm: "18px" },
                fontWeight: 500,
                lineHeight: { xs: "26px", sm: "30px" },
                color: "#646271",
                textAlign: "center",
                textWrap: "wrap",
              }}
            >
              <div
                dangerouslySetInnerHTML={{
                  __html: homeOverviewData?.description_2
                    ? `<style>p { margin: 0; }</style>${homeOverviewData?.description_2}`
                    : "",
                }}
              />
            </Typography>
          </Grid>
          {homeOverviewData && Object.keys(homeOverviewData).length > 0 && (
            <Grid item xs={12}>
              <Box sx={{ width: "100%" }}>
                <TabContext value={value}>
                  <Box
                    sx={{
                      borderBottom:
                        overviewList && overviewList?.length > 0 ? 1 : 0,
                      borderColor: "divider",
                    }}
                  >
                    <TabList
                      onChange={handleChange}
                      variant={
                        isMobile
                          ? overviewList?.length >= 4
                            ? "scrollable"
                            : "fullWidth"
                          : isTablet
                          ? overviewList?.length >= 10
                            ? "scrollable"
                            : "fullWidth"
                          : isLarge
                          ? overviewList?.length >= 12
                            ? "scrollable"
                            : "fullWidth"
                          : "fullWidth" // Fallback in case none of the conditions match
                      }
                      aria-label="lab API tabs example"

                      // sx={{
                      //   "& .MuiTabs-flexContainer": {
                      //     display: "flex",
                      //     // justifyContent: "space-between",
                      //     // gap: 10,
                      //   },
                      // }}
                    >
                      {overviewList?.map((item, index) => (
                        <CustomTab
                          label={item.title}
                          value={item.title}
                          key={index}
                          // wrapped
                          sx={{
                            textAlign: "start", // Align text to the start (or left)
                          }}
                        />
                      ))}
                    </TabList>
                  </Box>
                  {overviewList?.map((item, index) => (
                    <Fade in={value === item.title} timeout={1000} key={index}>
                      <CustomTabPanel value={item.title}>
                        <IGASolutionOptionsCard
                          value={subOverviewData[item.title] || []}
                        />
                      </CustomTabPanel>
                    </Fade>
                  ))}
                </TabContext>
              </Box>
            </Grid>
          )}
        </Grid>
      </Container>
    </>
  );
};

export default IGASolutionOptions;
