import { Box, Container } from "@mui/material";
import React from "react";
import { MEDIA_URL } from "src/network/endpoints";

const OverviewImages = ({ overviewImages }) => {
  return (
    <>
      <Container
        maxWidth={"xl"}
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 20 },
          display: "flex",
          flexDirection: "column",
          gap: 10,
        }}
      >
        {overviewImages?.map((item, index) => (
          <Box key={index} sx={{ width: "100%" }}>
            <img
              src={
                item.image_url
                  ? item.image_url.startsWith(
                      "https://dwitst24.blob.core.windows.net/upload/"
                    )
                    ? item.image_url.replace(
                        "https://dwitst24.blob.core.windows.net/upload/",
                        MEDIA_URL
                      )
                    : item.image_url.startsWith("http")
                    ? item.image_url
                    : `${MEDIA_URL}${item.image_url}`
                  : "" // Fallback in case icon_image is null or empty
              }
              style={{
                width: "100%",
                borderRadius: "10px",
                height: "100%",
                maxHeight: "800px",
              }}
            />
          </Box>
        ))}
      </Container>
    </>
  );
};

export default OverviewImages;
